usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Invites.New(
		context.TODO(),
		openai.AdminOrganizationInviteNewParams{
			Email: "string",
			Role: openai.InviteRequestRoleReader,
			Projects: []openai.InviteRequestProjectsItem{openai.InviteRequestProjectsItem{ID: "string", Role: openai.InviteRequestProjectsItemRoleMember}},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
